// ─────────────────────────────────────────────────────────────────────────────
// PARSE AND MERGE AI PRODUCT DATA  (v5 — context-safe via Set Context)
//
// AUTHORITY MAP:
//   Sheet (via Set Context) → barcode, folderId, price, work, sareeType,
//                              occasion, style, fabric
//   AI    → color, productTitle, workDetails, borderAnalysis, palluAnalysis,
//            motifAnalysis, weavingDescription, seoDescription, tags
//
// Collections built ONLY from sheet: sareeType + occasion + style + fabric.
// Color comes from AI visual analysis — never from sheet.
// Work comes from sheet — AI uses it for context only.
// ─────────────────────────────────────────────────────────────────────────────

const aiRaw = $input.first().json;
const ctx   = $('Set Context').first().json;

// ── Helper functions ──────────────────────────────────────────────────────────
function findText(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (value.content && Array.isArray(value.content.parts))
    return value.content.parts.map(p => p.text || '').join('\n');
  if (value.text)     return String(value.text);
  if (value.output)   return typeof value.output === 'string' ? value.output : findText(value.output);
  if (value.response) return typeof value.response === 'string' ? value.response : findText(value.response);
  if (Array.isArray(value)) {
    for (const e of value) { const f = findText(e); if (f) return f; }
  }
  if (typeof value === 'object') {
    for (const k of Object.keys(value)) {
      const f = findText(value[k]);
      if (f && f.includes('{')) return f;
    }
  }
  return JSON.stringify(value);
}

function cleanJsonText(text) {
  let c = String(text || '').trim();
  if (c.startsWith('```')) {
    const nl = c.indexOf('\n');
    if (nl >= 0) c = c.slice(nl + 1).trim();
    if (c.endsWith('```')) c = c.slice(0, -3).trim();
  }
  const fb = c.indexOf('{'), lb = c.lastIndexOf('}');
  if (fb >= 0 && lb > fb) c = c.slice(fb, lb + 1);
  return c;
}

function toArray(v) {
  if (Array.isArray(v)) return v.filter(Boolean).map(x => String(x).trim()).filter(Boolean);
  if (!v) return [];
  return String(v).split(/[,\n]/).map(x => x.trim()).filter(Boolean);
}

function onlyPrice(v) {
  const t = String(v || '');
  let o = '';
  for (const ch of t) if ('0123456789.'.includes(ch)) o += ch;
  return o;
}

// ── Parse Gemini response ─────────────────────────────────────────────────────
let ai;
try {
  ai = JSON.parse(cleanJsonText(findText(aiRaw)));
} catch (err) {
  ai = {
    color: '',
    productTitle: ctx.barcode,
    workDetails: [],
    borderAnalysis: '',
    palluAnalysis: '',
    tags: [],
    parseError: err.message,
    rawGemini: findText(aiRaw)
  };
}

// ── Sheet values (authoritative, via Set Context) ──────────────────────────────
const price     = onlyPrice(ctx.price);
const work      = String(ctx.work || '').trim();       // from sheet
const sareeType = toArray(ctx.sareeType);
const occasion  = toArray(ctx.occasion);
const style     = toArray(ctx.style);
const fabric    = toArray(ctx.fabric);

// ── AI values ─────────────────────────────────────────────────────────────────
const color       = String(ai.color || '').trim();     // from AI vision
const workDetails = toArray(ai.workDetails);

// ── Collections: built ONLY from sheet taxonomy ───────────────────────────────
const collections = [...sareeType, ...occasion, ...style, ...fabric];

// ── Tags: AI design tags + collections + AI color (deduped) ──────────────────
const tags = toArray(ai.tags);
for (const t of collections) if (t && !tags.includes(t)) tags.push(t);
if (color && !tags.includes(color)) tags.push(color);

// ── Wash care (standard) ──────────────────────────────────────────────────────
const washCare = [
  'Dry Clean Recommended',
  'Do Not Bleach',
  'Steam Iron on Low Heat',
  'Dry in Shade'
];

// ── HTML description ──────────────────────────────────────────────────────────
const descriptionHtml =
  '<h3>Work Details</h3><ul>' +
  workDetails.map(w => '<li>' + w + '</li>').join('') +
  '</ul>' +
  (ai.seoDescription ? '<h3>About This Saree</h3><p>' + ai.seoDescription + '</p>' : '') +
  '<h3>Fabric Details</h3><p>' + fabric.join(', ') + '</p>' +
  '<h3>Wash Care</h3><ul>' + washCare.map(w => '<li>' + w + '</li>').join('') + '</ul>';

return [{
  json: {
    // Identifiers
    barcode:  ctx.barcode,
    folderId: ctx.folderId,

    // ── Sheet-authoritative ──
    price,
    work,          // from sheet
    sareeType,
    occasion,
    style,
    fabric,

    // ── AI-generated ──
    color,         // from Gemini visual analysis
    productTitle:       ai.productTitle  || ctx.barcode,
    workDetails,

    // ── Merged ──
    collections,
    tags,
    washCare,
    descriptionHtml,

    // Standard measurements
    sareeLength:  '5.50 Meter',
    blouseLength: '0.80 Meter',

    // Raw AI for downstream nodes
    aiParsed: ai
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// PRODUCT.JSON  (v3 schema)
//
// Sheet fields:   price, work, sareeType, occasionWise, style, fabricCategory
// AI fields:      color, productTitle, workDetails, tags
//   (+ borderAnalysis, palluAnalysis, motifAnalysis, weavingDescription, seoDescription)
// ─────────────────────────────────────────────────────────────────────────────
const p = $json;

const productJson = {
  // Identifiers
  barcode:        p.barcode,

  // ── Sheet-authoritative ──
  price:          p.price,
  work:           p.work,           // from sheet
  sareeType:      p.sareeType,
  occasionWise:   p.occasion,
  style:          p.style,
  fabricCategory: p.fabric,

  // ── AI-generated ──
  color:          p.color,          // from Gemini visual analysis
  productTitle:   p.productTitle,
  workDetails:    p.workDetails,
  borderAnalysis:     p.borderAnalysis,
  palluAnalysis:      p.palluAnalysis,
  motifAnalysis:      p.motifAnalysis,
  weavingDescription: p.weavingDescription,
  seoDescription:     p.seoDescription,
  tags:           p.tags
};

const jsonString = JSON.stringify(productJson, null, 2);

return [{
  json: p,
  binary: {
    data: {
      data:          Buffer.from(jsonString).toString('base64'),
      mimeType:      'application/json',
      fileName:      'product.json',
      fileExtension: 'json'
    }
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// BUILD DOC URL  (v5 — context-safe via Set Context)
// Extracts the Google Drive webViewLink from the saved DOCX response.
// Barcode is read from Set Context, never from a transient field that could
// have been overwritten by the Drive upload response.
// ─────────────────────────────────────────────────────────────────────────────
const driveFile = $('Save DOCX to Drive1').first().json;
const ctx       = $('Set Context').first().json;

const fileId = driveFile.id || driveFile.fileId || '';
const docUrl = driveFile.webViewLink ||
               (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');

return [{
  json: {
    barcode: ctx.barcode,
    docUrl,
    fileId
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// COLLECT ERROR CONTEXT  (v5 — context-safe via Set Context)
// Called from any error branch (Image Found? = false, or Will Retry? = false
// after 3 Gemini attempts exhausted). Normalises everything into the
// detailed error-logging schema: Error Reason, Error Type, Failed Node,
// Failed At. Barcode and Folder ID always come from Set Context first,
// falling back to the current item only if Set Context is unreachable.
// ─────────────────────────────────────────────────────────────────────────────
function getContext() {
  try {
    return $('Set Context').first().json;
  } catch (e) {
    return {};
  }
}

const input = $input.first().json;
const ctx   = getContext();

const barcode  = ctx.barcode  || input.barcode  || 'UNKNOWN';
const folderId = ctx.folderId || input.folderId || '';

// If we arrived here from Classify Gemini Error / Classify Folder Error
// (i.e. retries exhausted or Drive failure), the error type/reason/node
// are already classified.
let errorType   = input.errorType   || '';
let errorReason = input.errorReason || '';
let failedNode  = input.failedNode  || '';

// Otherwise (e.g. Image Found? = false branch) classify here directly.
if (!errorType) {
  errorReason = input.reason ||
                input.error?.message ||
                input.message ||
                JSON.stringify(input).slice(0, 300);
  failedNode  = input.failedNode || 'Unknown Node';
  errorType   = input.errorType || 'Image Processing Error';
}

return [{
  json: {
    barcode,
    folderId,
    errorReason: String(errorReason).slice(0, 500),
    errorType,
    failedNode,
    failedAt: new Date().toISOString()
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// GENERATE DOCX DIRECTLY  (v5 — context-safe, guarantees IBM Plex Sans)
//
// Builds a minimal, valid .docx (OOXML WordprocessingML inside a ZIP
// container) entirely in JS, with no external dependencies. Every text run
// explicitly declares <w:rFonts w:ascii="IBM Plex Sans" w:hAnsi="IBM Plex Sans"
// w:cs="IBM Plex Sans"/>, so the font is baked into the document XML itself
// rather than depending on Google Drive's HTML->Docs font substitution
// (which is the root cause of the intermittent font loss).
//
// CONTEXT SAFETY: by the time this node runs, $input.first().json is the
// Drive file metadata returned by "Upload file" — NOT the product data.
// Inventory fields are therefore always read from Set Context, and
// AI-generated fields are always read from Parse and Merge AI Product
// Data1 by name, never from the (lossy) immediate input.
//
// Formatting preserved exactly as before:
//   Heading color  #3D85C6   size 14pt (28 half-points)  bold
//   Body text      size 11pt (22 half-points)
//   Bullets        standard Word bullet list (numbering.xml)
// ─────────────────────────────────────────────────────────────────────────────

const ctx = $('Set Context').first().json;
const ai  = $('Parse and Merge AI Product Data1').first().json;

const p = {
  barcode:            ctx.barcode,
  folderId:           ctx.folderId,
  price:              ctx.price,
  work:               ctx.work,
  sareeType:          ctx.sareeType,
  occasion:           ctx.occasion,
  style:              ctx.style,
  fabric:             ai.fabric || ctx.fabric,
  color:              ai.color,
  productTitle:       ai.productTitle,
  workDetails:        ai.workDetails,
  motifAnalysis:      ai.motifAnalysis,
  weavingDescription: ai.weavingDescription,
  seoDescription:     ai.seoDescription,
  collections:        ai.collections,
  washCare:           ai.washCare
};

// ---- helpers ---------------------------------------------------------------
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&apos;');

const BODY_FONT    = 'IBM Plex Sans';
const HEADING_FONT = 'Cambria';

function rPr(opts = {}) {
  const {
    bold,
    color,
    size,
    font = BODY_FONT
  } = opts;

  let xml = '<w:rPr>';

  xml += `<w:rFonts
    w:ascii="${font}"
    w:hAnsi="${font}"
    w:cs="${font}"
    w:eastAsia="${font}"/>`;

  if (bold) xml += '<w:b/>';
  if (color) xml += `<w:color w:val="${color}"/>`;

  xml += `<w:sz w:val="${size || 22}"/>`;
  xml += `<w:szCs w:val="${size || 22}"/>`;

  xml += '</w:rPr>';

  return xml;
}

function run(text, opts = {}) {
  return `<w:r>${rPr(opts)}<w:t xml:space="preserve">${esc(text)}</w:t></w:r>`;
}

function heading(text) {
  return `<w:p>
    <w:pPr>
      <w:pStyle w:val="Heading2"/>
      <w:spacing w:before="280" w:after="40"/>
    </w:pPr>
    ${run(text, {
      font: 'Cambria',
      bold: true,
      color: '3D85C6',
      size: 34
    })}
  </w:p>`;
}


function paragraph(text) {
  return `<w:p>
    <w:pPr>
      <w:spacing w:before="0" w:after="160"/>
    </w:pPr>
    ${run(text, {
      font: BODY_FONT,
      size: 22
    })}
  </w:p>`;
}

function bullet(text) {
  return `<w:p>
    <w:pPr>
      <w:numPr>
        <w:ilvl w:val="0"/>
        <w:numId w:val="1"/>
      </w:numPr>
      <w:spacing w:before="0" w:after="40"/>
    </w:pPr>
    ${run(text, {
      font: BODY_FONT,
      size: 22
    })}
  </w:p>`;
}

function section(title, bodyParas) {
  let xml = heading(title);
  for (const para of bodyParas) {
    xml += Array.isArray(para) ? para.map(bullet).join('') : paragraph(para);
  }
  return xml;
}

function fabricBullet(label, value) {
  return `<w:p>
    <w:pPr>
      <w:numPr>
        <w:ilvl w:val="0"/>
        <w:numId w:val="1"/>
      </w:numPr>
      <w:spacing w:before="0" w:after="40"/>
    </w:pPr>

    <w:r>
      ${rPr({
        font: BODY_FONT,
        size: 22,
        bold: true
      })}
      <w:t xml:space="preserve">${esc(label + ': ')}</w:t>
    </w:r>

    <w:r>
      ${rPr({
        font: BODY_FONT,
        size: 22
      })}
      <w:t xml:space="preserve">${esc(value)}</w:t>
    </w:r>

  </w:p>`;
}

function numberedItem(text) {
  return `<w:p>
    <w:pPr>
      <w:numPr>
        <w:ilvl w:val="0"/>
        <w:numId w:val="2"/>
      </w:numPr>
      <w:spacing w:before="0" w:after="40"/>
    </w:pPr>
    ${run(text, {
      font: BODY_FONT,
      size: 22
    })}
  </w:p>`;
}

// ---- assemble document body -------------------------------------------------
const safe    = (v, fb = '') => String(v || '').trim() || fb;
const safeArr = (v) => Array.isArray(v) ? v.filter(x => String(x || '').trim()) : (v ? [String(v).trim()] : []);

let body = '';
body += heading('Product Title');
body += paragraph(safe(p.productTitle));
body += section('Price', [p.price ? `\u20b9 ${p.price}` : '']);
body += section('Color', [safe(p.color)]);
body += section('Work Details', [safeArr(p.workDetails)]);
// Fabric Details
body += heading('Fabric Details');

const fabricValue = safeArr(p.fabric).join(', ');

body += fabricBullet('Saree Fabric', fabricValue);
body += fabricBullet('Blouse Fabric', fabricValue);
body += fabricBullet('Saree Length', '5.50 Meter');
body += fabricBullet('Blouse Length', '0.80 Meter');

// Wash Care
body += section('Wash Care', [safeArr(p.washCare)]);

// Collections
body += heading('Collections');

safeArr(p.collections).forEach(item => {
  body += numberedItem(item);
});



// ---- OOXML parts -------------------------------------------------------------
const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
<w:body>
${body}
<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720" w:gutter="0"/></w:sectPr>
</w:body>
</w:document>`;

const numberingXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">

  <!-- BULLETS -->
  <w:abstractNum w:abstractNumId="0">
    <w:multiLevelType w:val="hybridMultilevel"/>

    <w:lvl w:ilvl="0">
      <w:start w:val="1"/>
      <w:numFmt w:val="bullet"/>
      <w:lvlText w:val=""/>
      <w:lvlJc w:val="left"/>

      <w:pPr>
        <w:ind w:left="720" w:hanging="360"/>
      </w:pPr>

      <w:rPr>
        <w:rFonts
          w:ascii="Symbol"
          w:hAnsi="Symbol"
          w:hint="default"/>
      </w:rPr>
    </w:lvl>
  </w:abstractNum>

  <w:num w:numId="1">
    <w:abstractNumId w:val="0"/>
  </w:num>

  <!-- NUMBERED LIST -->
  <w:abstractNum w:abstractNumId="1">
    <w:multiLevelType w:val="hybridMultilevel"/>

    <w:lvl w:ilvl="0">
      <w:start w:val="1"/>
      <w:numFmt w:val="decimal"/>
      <w:lvlText w:val="%1."/>
      <w:lvlJc w:val="left"/>

      <w:pPr>
        <w:ind w:left="720" w:hanging="360"/>
      </w:pPr>

      <w:rPr>
        <w:rFonts
          w:ascii="${BODY_FONT}"
          w:hAnsi="${BODY_FONT}"
          w:cs="${BODY_FONT}"
          w:eastAsia="${BODY_FONT}"/>
      </w:rPr>
    </w:lvl>
  </w:abstractNum>

  <w:num w:numId="2">
    <w:abstractNumId w:val="1"/>
  </w:num>

</w:numbering>`;


const stylesXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">

<w:docDefaults>
  <w:rPrDefault>
    <w:rPr>
      <w:rFonts
        w:ascii="${BODY_FONT}"
        w:hAnsi="${BODY_FONT}"
        w:cs="${BODY_FONT}"
        w:eastAsia="${BODY_FONT}"/>
      <w:sz w:val="22"/>
      <w:szCs w:val="22"/>
    </w:rPr>
  </w:rPrDefault>
</w:docDefaults>

<w:style w:type="paragraph" w:default="1" w:styleId="Normal">
  <w:name w:val="Normal"/>
</w:style>

<w:style w:type="paragraph" w:styleId="Heading2">
  <w:name w:val="Heading 2"/>

  <w:pPr>
    <w:outlineLvl w:val="1"/>
  </w:pPr>

  <w:rPr>
    <w:rFonts
      w:ascii="Cambria"
      w:hAnsi="Cambria"
      w:cs="Cambria"
      w:eastAsia="Cambria"/>

    <w:b/>
    <w:color w:val="3D85C6"/>

    <w:sz w:val="34"/>
    <w:szCs w:val="34"/>
  </w:rPr>
</w:style>

</w:styles>`;

const contentTypesXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>
<Override PartName="/word/numbering.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.numbering+xml"/>
</Types>`;

const rootRelsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>`;

const docRelsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">

<Relationship
 Id="rId1"
 Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles"
 Target="styles.xml"/>

<Relationship
 Id="rId2"
 Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/numbering"
 Target="numbering.xml"/>

</Relationships>`;

// ---- minimal ZIP (STORED method, no compression dependency) ----------------
function crc32(buf) {
  let c, crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    c = (crc ^ buf[i]) & 0xFF;
    for (let j = 0; j < 8; j++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function zipFile(name, content) {
  const data = Buffer.from(content, 'utf8');
  const crc = crc32(data);
  const nameBuf = Buffer.from(name, 'utf8');

  const localHeader = Buffer.alloc(30);
  localHeader.writeUInt32LE(0x04034b50, 0);
  localHeader.writeUInt16LE(20, 4);
  localHeader.writeUInt16LE(0, 6);
  localHeader.writeUInt16LE(0, 8);  // STORED = no compression
  localHeader.writeUInt16LE(0, 10);
  localHeader.writeUInt16LE(0, 12);
  localHeader.writeUInt32LE(crc, 14);
  localHeader.writeUInt32LE(data.length, 18);
  localHeader.writeUInt32LE(data.length, 22);
  localHeader.writeUInt16LE(nameBuf.length, 26);
  localHeader.writeUInt16LE(0, 28);

  return {
    name, nameBuf, crc, size: data.length,
    local: Buffer.concat([localHeader, nameBuf, data])
  };
}

const parts = [
  zipFile('[Content_Types].xml', contentTypesXml),
  zipFile('_rels/.rels', rootRelsXml),
  zipFile('word/document.xml', documentXml),
  zipFile('word/styles.xml', stylesXml),
  zipFile('word/numbering.xml', numberingXml),
  zipFile('word/_rels/document.xml.rels', docRelsXml),
];

let offset = 0;
const localChunks = [];
const centralChunks = [];

for (const part of parts) {
  localChunks.push(part.local);
  const central = Buffer.alloc(46);
  central.writeUInt32LE(0x02014b50, 0);
  central.writeUInt16LE(20, 4);
  central.writeUInt16LE(20, 6);
  central.writeUInt16LE(0, 8);
  central.writeUInt16LE(0, 10);
  central.writeUInt16LE(0, 12);
  central.writeUInt16LE(0, 14);
  central.writeUInt32LE(part.crc, 16);
  central.writeUInt32LE(part.size, 20);
  central.writeUInt32LE(part.size, 24);
  central.writeUInt16LE(part.nameBuf.length, 28);
  central.writeUInt16LE(0, 30);
  central.writeUInt16LE(0, 32);
  central.writeUInt16LE(0, 34);
  central.writeUInt16LE(0, 36);
  central.writeUInt32LE(0, 38);
  central.writeUInt32LE(offset, 42);
  centralChunks.push(Buffer.concat([central, part.nameBuf]));
  offset += part.local.length;
}

const centralDirStart = offset;
const centralDir = Buffer.concat(centralChunks);
const centralDirSize = centralDir.length;

const eocd = Buffer.alloc(22);
eocd.writeUInt32LE(0x06054b50, 0);
eocd.writeUInt16LE(0, 4);
eocd.writeUInt16LE(0, 6);
eocd.writeUInt16LE(parts.length, 8);
eocd.writeUInt16LE(parts.length, 10);
eocd.writeUInt32LE(centralDirSize, 12);
eocd.writeUInt32LE(centralDirStart, 16);
eocd.writeUInt16LE(0, 20);

const zipBuffer = Buffer.concat([...localChunks, centralDir, eocd]);
const docTitle = p.barcode || 'product';

return [{
  json: { ...p, docTitle },
  binary: {
    data: {
      data: zipBuffer.toString('base64'),
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      fileName: docTitle + '.docx',
      fileExtension: 'docx'
    }
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// INIT GEMINI ATTEMPT COUNTER  (v4)
// Runs once per item, right before the first Gemini call.
// ─────────────────────────────────────────────────────────────────────────────
return $input.all().map(item => ({
  json: {
    ...item.json,
    geminiAttempt: 1
  },
  binary: item.binary
}));

// ─────────────────────────────────────────────────────────────────────────────
// CLASSIFY GEMINI ERROR  (v5 — context-safe via Set Context)
//
// Inspects the error payload n8n attaches when a node's continueErrorOutput
// fires, classifies it into one of the documented Error Type buckets, and
// decides whether this attempt should be retried (attempt < 3) or whether
// we should give up and hand off to Mark as Error.
//
// All inventory fields (barcode, folderId, price, work, sareeType, occasion,
// style, fabric) are read from Set Context — never from the current $json,
// which at this point is only the error payload from the failed Gemini call.
// ─────────────────────────────────────────────────────────────────────────────
const errItem = $input.first().json;
const ctx     = $('Set Context').first().json;

function getAttempt() {
  if (errItem && errItem.geminiAttempt) return errItem.geminiAttempt;
  try {
    const retryItem = $('Restore Binary For Retry').first().json;
    if (retryItem && retryItem.geminiAttempt) return retryItem.geminiAttempt;
  } catch (e) { /* not reached yet */ }
  try {
    const initItem = $('Init Gemini Attempt Counter').first().json;
    if (initItem && initItem.geminiAttempt) return initItem.geminiAttempt;
  } catch (e) { /* not reached yet */ }
  return 1;
}

const attempt = getAttempt();

const rawMessage = String(
  errItem.error?.message ||
  errItem.message ||
  JSON.stringify(errItem)
).slice(0, 500);

function classify(msg) {
  const m = msg.toUpperCase();
  if (m.includes('429') || m.includes('RESOURCE_EXHAUSTED') || m.includes('QUOTA_EXCEEDED') ||
      m.includes('DEADLINE_EXCEEDED') || m.includes('INTERNAL')) {
    return 'Rate Limit';
  }
  if (m.includes('SAFETY') || m.includes('BLOCKED') || m.includes('RECITATION')) {
    return 'Safety Block';
  }
  if (m.includes('JSON') || m.includes('UNEXPECTED TOKEN') || m.includes('PARSE')) {
    return 'Invalid JSON';
  }
  if (m.includes('TIMEOUT') || m.includes('UNSUPPORTED') || m.includes('SIZE') || m.includes('TOO LARGE')) {
    return 'Image Processing Error';
  }
  if (m.includes('ECONNRESET') || m.includes('ENOTFOUND') || m.includes('NETWORK') || m.includes('ETIMEDOUT')) {
    return 'Network Error';
  }
  return 'Unknown Error';
}

const errorType = classify(rawMessage);
const willRetry = attempt < 3;

return [{
  json: {
    barcode:       ctx.barcode,
    folderId:      ctx.folderId,
    price:         ctx.price,
    work:          ctx.work,
    sareeType:     ctx.sareeType,
    occasion:      ctx.occasion,
    style:         ctx.style,
    fabric:        ctx.fabric,
    geminiAttempt: attempt,
    errorType,
    errorReason: rawMessage,
    failedNode: 'Analyze an image',
    willRetry
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// INCREMENT RETRY + SET BACKOFF  (v4)
// Attempt 1 -> immediate (0s wait already happened)
// Attempt 2 -> wait 30s before retry
// Attempt 3 -> wait 60s before retry
// ─────────────────────────────────────────────────────────────────────────────
const j = $input.first().json;
const nextAttempt = (j.geminiAttempt || 1) + 1;

// backoff applies to the attempt we are ABOUT to make:
// going into attempt 2 -> wait 30s; going into attempt 3 -> wait 60s
const backoffSeconds = nextAttempt === 2 ? 5 : (nextAttempt === 3 ? 10 : 0);

return [{
  json: {
    ...j,
    geminiAttempt: nextAttempt,
    backoffSeconds
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// RESTORE BINARY FOR RETRY  (v5 — context-safe via Set Context)
// Re-attaches the originally downloaded image binary before retrying
// Gemini, since the error-handling branch only carries JSON forward.
// Binary always comes from "Download -2 Image" (the original download,
// never overwritten). Inventory fields always come from Set Context.
// ─────────────────────────────────────────────────────────────────────────────
const ctx    = $('Set Context').first().json;
const binary = $('Download -5 Image').first().binary || {};

return [{
  json: { ...$input.first().json, ...ctx, geminiAttempt: $input.first().json.geminiAttempt },
  binary
}];

// ─────────────────────────────────────────────────────────────────────────────
// CLASSIFY FOLDER/DRIVE ERROR  (v5 — context-safe via Set Context)
// Handles failures from List Folder Files (e.g. invalid or deleted Folder ID
// read from the sheet). Barcode and Folder ID always come from Set Context.
// ─────────────────────────────────────────────────────────────────────────────
const errItem = $input.first().json;
const ctx     = $('Set Context').first().json;

const rawMessage = String(
  errItem.error?.message || errItem.message || JSON.stringify(errItem)
).slice(0, 500);

return [{
  json: {
    barcode:     ctx.barcode,
    folderId:    ctx.folderId,
    errorReason: rawMessage,
    errorType:   'Google Drive Error',
    failedNode:  'List Folder Files',
    failedAt:    new Date().toISOString()
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// SELECT -2 IMAGE  (v5 — STRICT, no fallback, context-safe via Set Context)
//
// RULE: Only the file ending with -2.jpg / -2.jpeg / -2.png / -2.webp is valid.
// If that file does not exist: imageFound = false → routes to Mark as Error.
// The -1 price tag and all other images are NEVER sent to Gemini.
//
// Inventory fields (barcode, folderId, price, work, sareeType, occasion,
// style, fabric) are NOT carried on this item's json — every downstream
// node reads them directly from $('Set Context').item.json.* instead.
// ─────────────────────────────────────────────────────────────────────────────
const ctx     = $('Set Context').first().json;
const barcode = ctx.barcode;
const files   = $input.all().map(i => i.json);

// Strict: must end with -2.<ext>
const primary = files.find(f => /5\.(jpg|jpeg|png|webp)$/i.test(f.name || ''));

if (!primary) {
  return [{
    json: {
      imageFound: false,
      barcode,
      folderId:   ctx.folderId,
      reason:     '5 image not found in folder (required: barcode-2.jpg/jpeg/png/webp)',
      failedNode: 'Select 5 Image',
      errorType:  'Image Processing Error'
    }
  }];
}

return [{
  json: {
    imageFound:       true,
    barcode,
    folderId:         ctx.folderId,
    primaryImageId:   primary.id,
    primaryImageName: primary.name
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// FILTER & NORMALISE SHEET ROWS  (v4)
//
// Processes:  Status blank | Pending | Error
//             Status = Processing AND Processing Started At > 2 hours ago
// Skips:      Status = Done
//             Status = Processing AND Processing Started At < 2 hours ago
//
// NEW (v4): Reads Folder ID directly from the sheet. Drive folder search /
// name-matching is no longer used anywhere in this workflow.
// ─────────────────────────────────────────────────────────────────────────────
const TWO_HOURS_MS = 2 * 60 * 60 * 1000;
const now = Date.now();

const s   = (v) => String(v || '').trim();
const arr = (v) => {
  const str = s(v);
  if (!str) return [];
  return str.split(/[,;\n]+/).map(x => x.trim()).filter(Boolean);
};

const rows = $input.all();
const processable = [];

for (const item of rows) {
  const row = item.json;

  const barcode = s(row['Barcode'] || row['barcode'] || '');
  if (!barcode) continue;  // skip empty rows

  const folderId = s(row['Folder ID'] || row['folderId'] || row['Folder Id'] || '');

  // Normalise status to Title-case
  const rawStatus = s(row['Status'] || row['status'] || '');
  const status = rawStatus.charAt(0).toUpperCase() + rawStatus.slice(1).toLowerCase();

  // ── Skip logic ────────────────────────────────────────────────────────────
  if (status === 'Done') continue;

  if (status === 'Processing') {
    const startedAt = s(row['Processing Started At'] || row['processing_started_at'] || '');
    if (startedAt) {
      const startedMs = new Date(startedAt).getTime();
      if (!isNaN(startedMs) && (now - startedMs) < TWO_HOURS_MS) {
        // Still within 2-hour window — skip (another execution is likely running)
        continue;
      }
      // Older than 2 hours → treat as stuck, re-process
    }
    // No timestamp → treat as stuck, re-process
  }

  // ── Accepted: blank, Pending, Error, or stuck Processing ─────────────────
  processable.push({
    json: {
      barcode,
      folderId,        // NEW — read directly from sheet, replaces Drive search
      status,
      processedAt:        s(row['Processed At']           || ''),
      processingStartedAt:s(row['Processing Started At']  || ''),
      docUrl:             s(row['Doc URL']                || ''),
      // ── Sheet-authoritative product fields ──
      price:     s(row['Price']       || row['price']      || row['MRP'] || ''),
      work:      s(row['Work']        || row['work']       || ''),
      sareeType: arr(row['Saree Type(s)'] || row['Saree Type'] || row['sareeType'] || ''),
      occasion:  arr(row['Occasion(s)']   || row['Occasion']   || row['occasion']  || ''),
      style:     arr(row['Style(s)']      || row['Style']      || row['style']     || ''),
      fabric:    arr(row['Fabric(s)']     || row['Fabric']     || row['fabric']    || ''),
      imageUrl:  s(row['Image URL']   || row['image_url']  || '')
      // NOTE: color is NOT read from sheet — Gemini determines it
    }
  });
}

return processable;

// ─────────────────────────────────────────────────────────────────────────────
// SET CONTEXT  (v5 — master context source)
//
// Single source of truth for every identifier / inventory field needed for
// this item. Every downstream node MUST read these values via
// $('Set Context').item.json.* instead of relying on transient $json fields,
// which can be overwritten or stripped by Google Drive, Google Sheets,
// HTTP Request, or Gemini nodes anywhere later in the branch.
// ─────────────────────────────────────────────────────────────────────────────
const row = $input.first().json;

return [{
  json: {
    barcode:   row.barcode   || '',
    folderId:  row.folderId  || '',
    price:     row.price     || '',
    work:      row.work      || '',
    sareeType: row.sareeType || [],
    occasion:  row.occasion  || [],
    style:     row.style     || [],
    fabric:    row.fabric    || [],
    imageUrl:  row.imageUrl  || '',
    docUrl:    row.docUrl    || ''
  }
}];
